var n=`0404-scotch-eggs`;var t=`world-0404`;var i=`GB`;var r=`northern-europe`;var a=4;var l=46;var s={en:`Scotch Eggs`,ua:`Яйця по-шотландськи`};var g={en:`A traditional dish from United Kingdom, centered on chicken egg, ground pork, sage, all-purpose flour. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: куряче яйце, свинячий фарш, шавлія, пшеничне борошно універсальне. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Boil the eggs for about 8 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 8 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:8,i:[[`chicken-egg`,4,`pcs`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`ground-pork`,500,`g`],[`sage`,3,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Peel the four cooked eggs. Encase each completely in an even layer of seasoned pork mince; use a separate uncooked egg for breading.`,ua:`Очистьте чотири варені яйця. Обгорніть кожне рівним шаром приправленого свинячого фаршу; для панірування використайте окреме сире яйце.`,t:[`rolling-stuffed-food`],m:12,i:[]},{en:`Pat dry, then coat evenly with the listed breading or flour components; press lightly to help it adhere.`,ua:`Обсушіть продукти й рівномірно запаніруйте їх у зазначених сухих складниках; злегка притисніть паніровку.`,t:[`standard-breading`],m:7,i:[[`all-purpose-flour`,60,`g`],[`chicken-egg`,1,`pcs`],[`breadcrumbs`,150,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 11 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 11 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:11,i:[[`sunflower-oil`,700,`ml`]]}];var u={slug:n,id:t,country:`GB`,region:r,servings:4,minutes:46,title:s,text:g,steps:d};export{i as country,u as default,t as id,l as minutes,r as region,a as servings,n as slug,d as steps,g as text,s as title};